From bf21861e89e50caad342043d4dcffdd30d5e9434 Mon Sep 17 00:00:00 2001
From: Ned Twigg <ned.twigg@diffplug.com>
Date: Thu, 1 Dec 2016 18:11:25 -0800
Subject: [PATCH] Fixed unused imports, and fixed a bug I introduced in
 7434506f7fd3a069f899c1d535eaf0a876306c6f.


diff --git a/src/main/java/com/diffplug/gradle/oomph/ConventionJdt.java b/src/main/java/com/diffplug/gradle/oomph/ConventionJdt.java
index 9cf914d..b1502b8 100644
--- a/src/main/java/com/diffplug/gradle/oomph/ConventionJdt.java
+++ b/src/main/java/com/diffplug/gradle/oomph/ConventionJdt.java
@@ -16,9 +16,7 @@
 package com.diffplug.gradle.oomph;

 import java.util.HashSet;
-import java.util.LinkedHashMap;
 import java.util.List;
-import java.util.Map;
 import java.util.Set;

 import org.gradle.api.Action;
@@ -77,7 +75,7 @@ public class ConventionJdt extends OomphConvention {
 				"org.eclipse.jdt.core.compiler.compliance",
 				"org.eclipse.jdt.core.compiler.source");
 		extension.workspaceProp(JDT_CORE_PREFS, props -> {
-			JDT_COMPLIANCE_PROPS.forEach(p -> props.put(p, compilerComplianceLevel.toString()));
+			JDT_COMPLIANCE_PROPS.forEach(p -> props.put(p, JavaVersion.toVersion(compilerComplianceLevel).toString()));
 			//Use default compliance settings.
 			props.put("org.eclipse.jdt.core.compiler.codegen.inlineJsrBytecode", "enabled");
 			props.put("org.eclipse.jdt.core.compiler.problem.assertIdentifier", "error");
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by incorrectly setting the Java compiler compliance properties using `compilerComplianceLevel.toString()`, which did not properly convert the compliance level to a valid Java version string. This could lead to issues in the compilation process, as the expected format for the compliance level was not adhered to. The fix involved using `JavaVersion.toVersion(compilerComplianceLevel).toString()` to ensure the compliance level is correctly represented as a version string.

        Commit message:
        Fixed unused imports, and fixed a bug I introduced in
 7434506f7fd3a069f899c1d535eaf0a876306c6f.  

        Patch:

 import java.util.HashSet;
-import java.util.LinkedHashMap;
 import java.util.List;
-import java.util.Map;
 import java.util.Set;

 	/** Sets default compliance level */
 	public void compilerComplianceLevel(String compilerComplianceLevel) {
 		List<String> JDT_COMPLIANCE_PROPS = ImmutableList.of(
 				"org.eclipse.jdt.core.compiler.codegen.targetPlatform",
 				"org.eclipse.jdt.core.compiler.compliance",
 				"org.eclipse.jdt.core.compiler.source");
 		extension.workspaceProp(JDT_CORE_PREFS, props -> {
-			JDT_COMPLIANCE_PROPS.forEach(p -> props.put(p, compilerComplianceLevel.toString()));
+			JDT_COMPLIANCE_PROPS.forEach(p -> props.put(p, JavaVersion.toVersion(compilerComplianceLevel).toString()));
 			//Use default compliance settings.
 			props.put("org.eclipse.jdt.core.compiler.codegen.inlineJsrBytecode", "enabled");
 			props.put("org.eclipse.jdt.core.compiler.problem.assertIdentifier", "error");
 			props.put("org.eclipse.jdt.core.compiler.problem.enumIdentifier", "error");
 		});
 	}



